// Get input data
const inputData = $input.all();

// Array to store all credit notes
const allCreditNotes = [];

// Get the date range passed to the webhook (if any)
let fromDate = '';
let toDate = '';
try {
  const q = $('Webhook1').first().json.query || {};
  fromDate = q.from_date || '';
  toDate = q.to_date || '';
} catch (e) {
  // No webhook query available (e.g. manual run) -> do not filter by date
}

// Loop through each input item
for (const item of inputData) {
  const data = item.json;

  // Check if creditnotes array exists
  if (data.creditnotes && Array.isArray(data.creditnotes)) {
    data.creditnotes.forEach(creditNote => {
      const cnDate = creditNote.date || '';

      // Filter by date range ONLY when the webhook supplied dates.
      // Dates are 'YYYY-MM-DD' so string comparison is safe.
      if (fromDate && cnDate < fromDate) return;
      if (toDate && cnDate > toDate) return;

      allCreditNotes.push({
        json: creditNote
      });
    });
  }
}

// Return all credit notes (within range) as separate items
return allCreditNotes;

const items = $input.all();
const results = [];

for (const item of items) {
  if (item.json.error) {
    const errorMessage = item.json.error.message || "";
    const match = errorMessage.match(/external ID '([^']+)'/);
    const contactNumber = match ? match[1] : "Unknown";

    results.push({
      json: {
        customer_exists: "no",
        contact_number: contactNumber
      }
    });
  } else {
    const customerData = typeof item.json.data === "string"
      ? JSON.parse(item.json.data)
      : (item.json.data || item.json);

    results.push({
      json: {
        customer_exists: "yes",
        ...customerData
      }
    });
  }
}

return results;

const sourceItems = $('Filter Records').all().map(item => item.json || {});

function hasValue(value) {
  if (Array.isArray(value)) return value.length > 0;
  if (value === null || value === undefined) return false;
  return String(value).trim() !== '';
}

for (const item of $input.all()) {
  const fullDetail = item.json || {};
  const creditNote = fullDetail.creditnote || fullDetail;
  const creditNoteId = creditNote.creditnote_id || fullDetail.creditnote_id || '';
  const source = sourceItems.find(sourceItem => sourceItem.creditnote_id === creditNoteId) || {};
  const fetchedAppliedInvoices = source.applied_invoices;

  if (hasValue(fetchedAppliedInvoices)) {
    creditNote.applied_invoice_numbers = fetchedAppliedInvoices;

    if (!hasValue(creditNote.applied_invoices)) {
      creditNote.applied_invoices = fetchedAppliedInvoices;
    }
  }

  if (fullDetail.creditnote) {
    fullDetail.creditnote = creditNote;
  }
}

return $input.all();

const items = $input.all();
const results = [];

for (const item of items) {
  const parsed = JSON.parse(item.json.data);

  for (const nsItem of parsed.items) {
    results.push({
      json: {
        id: nsItem.id,
        itemid: nsItem.itemid,
        displayname: nsItem.displayname
      }
    });
  }
}

return results;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const mergedItems = $input.all();
const creditNote = $('Return Credit Data').first().json.creditnote;

// Extract customer (first item) and NS items (rest)
const customer = mergedItems[0].json;
const nsItems = mergedItems.slice(1).map(i => i.json);

return [
  {
    json: {
      // Credit note info
      creditnote_id: creditNote.creditnote_id,
      creditnote_number: creditNote.creditnote_number,
      date: creditNote.date,
      contact_number: creditNote.contact_number,
      customer_name: creditNote.customer_name,
      total: creditNote.total,
      memo: creditNote.notes,
      creditnote_refunds: creditNote.creditnote_refunds || [],
      total_refund: creditNote.total_refund || 0,

      // Invoices this credit note is applied to
      applied_invoices: (creditNote.invoices || []).map(inv => ({
        invoice_id: inv.invoice_id,
        invoice_number: inv.invoice_number,
        credited_amount: inv.credited_amount,
        date: inv.date
      })),

      // Customer info from NetSuite
      ns_customer_id: customer.id,
      ns_subsidiary_id: customer.subsidiary.id,
      ns_currency_id: customer.currency.id,

      // Line items matched with NS item IDs
      line_items: (creditNote.line_items || creditNote.creditnote_items || []).map((zohoItem, index) => ({
        ns_item_id: nsItems[index]?.id || null,
        name: zohoItem.name,
        quantity: zohoItem.quantity,
        rate: zohoItem.rate ?? zohoItem.price,
        amount: zohoItem.item_total,
        description: zohoItem.description
      }))
    }
  }
];

const data = $input.first().json;

const date = new Date(data.date);
const memo = `Credit Memo for ${date.toLocaleString('default', { month: 'long' })} ${date.getFullYear()}`;

const output = [
  {
    json: {
      externalId: data.creditnote_number,
      tranId: data.creditnote_number,
      entity: {
        externalId: data.contact_number
      },
      subsidiary: {
        id: "1"
      },
      location: "525",
      tranDate: data.date,
      memo: memo,
      item: {
        items: data.line_items.map(line => ({
          item: {
            id: line.ns_item_id
          },
          quantity: line.quantity,
          rate: line.rate,
          amount: line.amount
        }))
      },
      apply: {
        items: data.applied_invoices.map(inv => ({
          doc: {
            externalId: inv.invoice_number
          },
          apply: true,
          amount: inv.credited_amount
        }))
      }
    }
  }
];
if (!data.applied_invoices.length) delete output[0].json.apply;
if ((data.creditnote_refunds || []).length || Number(data.total_refund || 0)>0) output[0].json.autoApply=false;
return output;

function readResponse(raw) {
  let body = raw.body ?? raw.data ?? raw;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {message:body}; } }
  return {status:Number(raw.statusCode || raw.error?.statusCode || raw.error?.httpCode || 0), body:body || {}, error:raw.error};
}
function errorText(r) { return String(r.body?.['o:errorDetails']?.map(e => e.detail).join('; ') || r.body?.message || r.error?.message || r.error || ('HTTP ' + r.status)); }
function result(json) { return [{json,pairedItem:{item:0}}]; }

const r=readResponse($input.first().json);
return result({memo_created:!r.error && r.status >= 200 && r.status < 300,error:errorText(r)});

return [
  {
    json: {
      creditnote_id: $('Return Credit Data').first().json.creditnote.creditnote_id
    }
  }
];

