const staticData = $getWorkflowStaticData('global');

staticData.creditMemoReport = {
  startedAt: new Date().toISOString(),
  rows: [],
};

return $input.all();

const staticData = $getWorkflowStaticData('global');

if (!staticData.creditMemoReport) {
  staticData.creditMemoReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

const statusData = $input.first().json || {};
const creditData = $('Return Credit Data').first().json.creditnote || {};

const invoiceNumber =
  creditData.creditnote_number ||
  creditData.creditnote_id ||
  'No Credit Note';

const customerName =
  creditData.customer_name ||
  '';

const amount =
  Number(creditData.total || 0);

function getInvoiceNumbers(creditData) {
  const invoiceNumbers = [];

  for (const invoice of creditData.invoices || []) {
    const number = invoice.invoice_number || invoice.invoiceNumber || invoice.number;
    if (number) {
      invoiceNumbers.push(String(number).trim());
    }
  }

  const appliedInvoices = creditData.applied_invoices || creditData.applied_invoice_numbers;
  if (Array.isArray(appliedInvoices)) {
    for (const invoice of appliedInvoices) {
      const number = typeof invoice === 'string'
        ? invoice
        : invoice.invoice_number || invoice.invoiceNumber || invoice.number;
      if (number) {
        invoiceNumbers.push(String(number).trim());
      }
    }
  } else if (appliedInvoices) {
    for (const number of String(appliedInvoices).split(',')) {
      if (number.trim()) {
        invoiceNumbers.push(number.trim());
      }
    }
  }

  return [...new Set(invoiceNumbers)].join(', ');
}

const invoiceNumbers = getInvoiceNumbers(creditData);

function parseNetSuiteError(errorValue) {
  const raw = typeof errorValue === 'object'
    ? JSON.stringify(errorValue)
    : String(errorValue || '');

  let text = raw.replace(/^\d+\s*-\s*/, '').trim();

  for (let i = 0; i < 3; i++) {
    if (text.startsWith('"') && text.endsWith('"')) {
      try {
        text = JSON.parse(text);
      } catch (error) {
        text = text.slice(1, -1).replace(/\\"/g, '"');
      }
    }
  }

  let parsed = null;
  try {
    parsed = JSON.parse(text);
  } catch (error) {
    parsed = null;
  }

  const detailObj = parsed?.['o:errorDetails']?.[0] || {};

  const errorCode =
    detailObj?.['o:errorCode'] ||
    parsed?.['o:errorCode'] ||
    '';

  const detail =
    detailObj?.detail ||
    parsed?.detail ||
    parsed?.message ||
    raw ||
    'Unknown NetSuite error';

  const lowerText = `${raw} ${detail} ${errorCode}`.toLowerCase();

  const externalIdMatch =
    detail.match(/external ID\s+([A-Za-z0-9_-]+)/i) ||
    raw.match(/external ID\s+([A-Za-z0-9_-]+)/i);

  const externalId = externalIdMatch ? externalIdMatch[1] : '';

  return {
    raw,
    errorCode,
    detail,
    lowerText,
    externalId,
  };
}

if (statusData.memo_created === true) {
  staticData.creditMemoReport.rows.push({
    status: 'SUCCESS',
    category: 'Credit Memos Created',
    invoiceNumber,
    invoiceNumbers,
    customerName,
    amount,
    stage: 'Credit Memo Created',
    message: `Credit memo created successfully for credit note ${invoiceNumber}.`,
  });
} else {
  const errorInfo = parseNetSuiteError(statusData.error);

  let category = 'Credit Memo Creation Failed';
  let stage = 'Credit Memo Creation';
  let message = `Credit memo could not be created or applied for credit note ${invoiceNumber}. Please review the NetSuite invoice/application setup.`;

  if (
    errorInfo.lowerText.includes('already exists') ||
    errorInfo.lowerText.includes('duplicate')
  ) {
    category = 'Duplicate Credit Memo Skipped';
    stage = 'Duplicate Check';
    message = `Credit memo already exists for credit note ${invoiceNumber}. Skipped to avoid duplicate.`;
  } else if (
    errorInfo.errorCode === 'NONEXISTENT_EXTERNAL_ID' ||
    errorInfo.lowerText.includes('does not exist') ||
    errorInfo.lowerText.includes('matching invoice was not found') ||
    errorInfo.lowerText.includes('external id')
  ) {
    category = 'Invoice Not Found in NetSuite';
    stage = 'Original Invoice Lookup';
    message = errorInfo.externalId
      ? `Credit note ${invoiceNumber} could not be applied because matching NetSuite invoice external ID ${errorInfo.externalId} was not found.`
      : `Credit note ${invoiceNumber} could not be applied because matching invoice was not found in NetSuite.`;
  } else if (
    errorInfo.errorCode === 'USER_ERROR' ||
    errorInfo.lowerText.includes('invalid sublist') ||
    errorInfo.lowerText.includes('line item operation')
  ) {
    category = 'Credit Memo Creation Failed';
    stage = 'Credit Memo Creation';
    message = `Credit memo could not be created or applied for credit note ${invoiceNumber}. Please review the NetSuite invoice/application setup.`;
  }

  staticData.creditMemoReport.rows.push({
    status: 'FAILED',
    category,
    invoiceNumber,
    invoiceNumbers,
    customerName,
    amount,
    stage,
    message,
  });
}

return $input.all();

const staticData = $getWorkflowStaticData('global');

if (!staticData.creditMemoReport) {
  staticData.creditMemoReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

const creditData = $('Return Credit Data').first().json.creditnote || {};
const customerCheck = $input.first().json || {};

const creditNoteNumber =
  creditData.creditnote_number ||
  creditData.creditnote_id ||
  'No Credit Note';

const customerName =
  creditData.customer_name ||
  '';

const contactNumber =
  creditData.contact_number ||
  customerCheck.contact_number ||
  'Unknown Customer';

const amount =
  Number(creditData.total || 0);

function getInvoiceNumbers(creditData) {
  const invoiceNumbers = [];

  for (const invoice of creditData.invoices || []) {
    const number = invoice.invoice_number || invoice.invoiceNumber || invoice.number;
    if (number) {
      invoiceNumbers.push(String(number).trim());
    }
  }

  const appliedInvoices = creditData.applied_invoices || creditData.applied_invoice_numbers;
  if (Array.isArray(appliedInvoices)) {
    for (const invoice of appliedInvoices) {
      const number = typeof invoice === 'string'
        ? invoice
        : invoice.invoice_number || invoice.invoiceNumber || invoice.number;
      if (number) {
        invoiceNumbers.push(String(number).trim());
      }
    }
  } else if (appliedInvoices) {
    for (const number of String(appliedInvoices).split(',')) {
      if (number.trim()) {
        invoiceNumbers.push(number.trim());
      }
    }
  }

  return [...new Set(invoiceNumbers)].join(', ');
}

const invoiceNumbers = getInvoiceNumbers(creditData);

staticData.creditMemoReport.rows.push({
  status: 'FAILED',
  category: 'Customer Not Found in NetSuite',
  invoiceNumber: creditNoteNumber,
  invoiceNumbers,
  customerName,
  amount,
  stage: 'Customer Lookup',
  message: `Customer ${contactNumber} was not found in NetSuite for credit note ${creditNoteNumber}.`,
});

return $input.all();

const staticData = $getWorkflowStaticData('global');

if (!staticData.creditMemoReport) {
  staticData.creditMemoReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

const creditData = $('Return Credit Data').first().json.creditnote || {};
const itemData = $('Separate Items').first().json || {};

const creditNoteNumber =
  creditData.creditnote_number ||
  creditData.creditnote_id ||
  'No Credit Note';

const customerName =
  creditData.customer_name ||
  '';

const itemName =
  itemData.item_name ||
  'Unknown Item';

const amount =
  Number(creditData.total || 0);

function getInvoiceNumbers(creditData) {
  const invoiceNumbers = [];

  for (const invoice of creditData.invoices || []) {
    const number = invoice.invoice_number || invoice.invoiceNumber || invoice.number;
    if (number) {
      invoiceNumbers.push(String(number).trim());
    }
  }

  const appliedInvoices = creditData.applied_invoices || creditData.applied_invoice_numbers;
  if (Array.isArray(appliedInvoices)) {
    for (const invoice of appliedInvoices) {
      const number = typeof invoice === 'string'
        ? invoice
        : invoice.invoice_number || invoice.invoiceNumber || invoice.number;
      if (number) {
        invoiceNumbers.push(String(number).trim());
      }
    }
  } else if (appliedInvoices) {
    for (const number of String(appliedInvoices).split(',')) {
      if (number.trim()) {
        invoiceNumbers.push(number.trim());
      }
    }
  }

  return [...new Set(invoiceNumbers)].join(', ');
}

const invoiceNumbers = getInvoiceNumbers(creditData);

staticData.creditMemoReport.rows.push({
  status: 'FAILED',
  category: 'Item Not Found in NetSuite',
  invoiceNumber: creditNoteNumber,
  invoiceNumbers,
  customerName,
  amount,
  stage: 'Item Lookup',
  message: `Item "${itemName}" was not found in NetSuite for credit note ${creditNoteNumber}.`,
});

return $input.all();

const staticData = $getWorkflowStaticData('global');

const report = staticData.creditMemoReport || {
  startedAt: new Date().toISOString(),
  rows: [],
};

const rows = report.rows || [];
const startedAt = report.startedAt || new Date().toISOString();
const completedAt = new Date().toISOString();

const successRows = rows.filter(row =>
  row.category === 'Credit Memos Created'
);

const duplicateRows = rows.filter(row =>
  row.category === 'Duplicate Credit Memo Skipped'
);

const missingRows = rows.filter(row =>
  row.category === 'Invoice Not Found in NetSuite' ||
  row.category === 'Customer Not Found in NetSuite' ||
  row.category === 'Item Not Found in NetSuite'
);

const failedRows = rows.filter(row =>
  row.status === 'FAILED' &&
  row.category !== 'Duplicate Credit Memo Skipped' &&
  row.category !== 'Invoice Not Found in NetSuite' &&
  row.category !== 'Customer Not Found in NetSuite' &&
  row.category !== 'Item Not Found in NetSuite'
);

return [
  {
    json: {
      workflowStatus: rows.some(row => row.status === 'FAILED')
        ? 'Completed with Exceptions'
        : 'Completed',

      startedAt,
      completedAt,

      totalReportedItems: rows.length,
      successCount: successRows.length,
      duplicateCount: duplicateRows.length,
      missingCount: missingRows.length,
      failedCount: failedRows.length,
      noEligibleCount: 0,
      refundCreatedCount: rows.filter(r=>r.category==='Customer Refund Created').length,
      refundExistingCount: rows.filter(r=>r.category==='Customer Refund Already Exists').length,
      refundFailedCount: rows.filter(r=>r.category==='Customer Refund Failed').length,

      reportRows: rows,
    },
  },
];

const summary = $input.first().json || {};

const rows = summary.reportRows || [];
const startedAt = summary.startedAt || new Date().toISOString();
const completedAt = summary.completedAt || new Date().toISOString();

const safeTimestamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
const parentExternalId = `CREDIT_NOTE_AUTOMATION_REPORT_${safeTimestamp}_${Math.floor(Math.random() * 100000)}`;

const summaryMessage =
  `Credit Note Automation completed. ` +
  `Total: ${summary.totalReportedItems || rows.length}, ` +
  `Created: ${summary.successCount || 0}, ` +
  `Missing: ${summary.missingCount || 0}, ` +
  `Failed: ${summary.failedCount || 0}. ` +
  `Refunds created: ${summary.refundCreatedCount || 0}, already present: ${summary.refundExistingCount || 0}, failed: ${summary.refundFailedCount || 0}.`;

const parentPayload = {
  externalId: parentExternalId,
  name: `Credit Note Automation Report - ${new Date().toISOString()}`,

  custrecordcmar_status: summary.workflowStatus || 'Executed',
  custrecordcmar_started: startedAt,
  custrecordcmar_completed: completedAt,

  custrecordcmar_total: Number(summary.totalReportedItems || rows.length || 0),
  custrecordcmar_created: Number(summary.successCount || 0),
  custrecordcmar_skipped: Number(summary.duplicateCount || 0),
  custrecordcmar_missing: Number(summary.missingCount || 0),
  custrecordcmar_failed: Number(summary.failedCount || 0),

  custrecordcmar_summary: summaryMessage,
};

return [
  {
    json: {
      parentPayload,
      parentExternalId,
      reportRows: rows,
    },
  },
];

const lookupRaw = $input.first().json || {};

let lookupResponse = lookupRaw;

if (typeof lookupRaw.data === 'string') {
  try {
    lookupResponse = JSON.parse(lookupRaw.data);
  } catch (error) {
    throw new Error('Could not parse SuiteQL lookup response data: ' + error.message);
  }
} else if (lookupRaw.data && typeof lookupRaw.data === 'object') {
  lookupResponse = lookupRaw.data;
}

const items =
  lookupResponse.items ||
  lookupResponse.body?.items ||
  lookupResponse.data?.items ||
  lookupRaw.items ||
  [];

const parentId =
  items?.[0]?.id ||
  items?.[0]?.ID ||
  lookupResponse.id ||
  lookupRaw.id ||
  lookupRaw.body?.id;

if (!parentId) {
  throw new Error(
    'Parent NetSuite report ID was not found from SuiteQL lookup. Actual input was: ' +
    JSON.stringify(lookupRaw)
  );
}

const parentData = $('Prepare NetSuite Parent Report Payload').first().json || {};
const allReportRows = parentData.reportRows || [];

function cleanText(value, maxLength = 300) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  return text.length > maxLength ? text.slice(0, maxLength) : text;
}

// Do not create child record for successful rows.
// Parent summary will still show created count.
const reportRows = allReportRows.filter(row => row.category !== 'Credit Memos Created');

return reportRows.map(row => {
  const category = row.category || 'Other';
  const creditNoteNumber = row.invoiceNumber || 'No Credit Note';
  const customerName = row.customerName || '';
  const stage = row.stage || 'Workflow Processing';
  const message = row.message || '';
  const invoiceNumbers = row.invoiceNumbers || '';

  return {
    json: {
      childPayload: {
        name: cleanText(`${creditNoteNumber} - ${category}`, 80),

        custrecordcmal_report: {
          id: String(parentId),
        },
        custrecordcmal_category: cleanText(category, 300),
        custrecord157: cleanText(invoiceNumbers, 300),
        custrecordcmal_invoice: cleanText(creditNoteNumber, 300),
        custrecordcmal_customer: cleanText(customerName, 300),
        custrecordcmal_amount: Number(row.amount || 0),
        custrecordcmal_stage: cleanText(stage, 300),
        custrecordcmal_message: cleanText(message, 300),
      },
      parentId: String(parentId),
    },
  };
});

// Refund settings. Edit these four values if the NetSuite account changes.
return [{
  json: {
    bankAccountId: '234',        // 10210 Chase Bank 1316-C
    refundPrefix: 'Refund-',     // document number = Refund-<credit note number>
    defaultLocationId: '525',    // same location the credit memo uses
    organizationId: '884904251', // Zoho production organization
  },
  pairedItem: { item: 0 },
}];

// --- shared helpers -------------------------------------------------
function readResponse(raw) {
  raw = raw || {};
  let body = raw.body ?? raw.data ?? raw;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { message: body }; } }
  const status = Number(raw.statusCode || raw.error?.statusCode || raw.error?.httpCode || 0);
  return { status, body: body || {}, error: raw.error, headers: raw.headers || {} };
}
function errorText(r) {
  const details = r.body?.['o:errorDetails'];
  if (Array.isArray(details) && details.length) return details.map(d => d.detail || d.message).join('; ');
  return String(r.body?.detail || r.body?.message || r.error?.message || r.error || ('HTTP ' + r.status));
}
function result(json) { return [{ json, pairedItem: { item: 0 } }]; }
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function reportStore() {
  const store = $getWorkflowStaticData('global');
  if (!store.creditMemoReport) store.creditMemoReport = { startedAt: new Date().toISOString(), rows: [] };
  return store.creditMemoReport;
}
// --------------------------------------------------------------------

const cn = $('Return Credit Data').first().json.creditnote || {};
const cfg = $('Refund Configuration').first().json;
const r = readResponse($input.first().json);

try {
  if (r.error || r.status < 200 || r.status >= 300 || !r.body.id) {
    throw new Error('The NetSuite credit memo for ' + cn.creditnote_number + ' could not be read back: ' + errorText(r));
  }
  const cm = r.body;
  if (!cm.entity || !cm.entity.id) throw new Error('Credit memo ' + cn.creditnote_number + ' has no customer on it.');

  // Zoho returns the refunds made against the credit note on the note itself.
  // Accept every field name Zoho Billing has used for it.
  const refunds = cn.creditnote_refunds || cn.refunds || [];
  const lineTotal = refunds.reduce((sum, ref) =>
    sum + (num(ref.amount_fcy) ?? num(ref.amount) ?? num(ref.amount_bcy) ?? 0), 0);
  const headerTotal = num(cn.total_refund) ?? num(cn.total_refunded_amount) ?? num(cn.refunded_amount) ?? 0;
  const amount = Number((lineTotal > 0 ? lineTotal : headerTotal).toFixed(2));
  if (!(amount > 0)) throw new Error('Credit note ' + cn.creditnote_number + ' has no refunded amount to post.');

  // Never refund more credit than the memo still holds.
  const remaining = num(cm.amountRemaining) ?? num(cm.unapplied);
  if (remaining !== null && amount > remaining + 0.005) {
    throw new Error('A refund of ' + amount + ' exceeds the ' + remaining + ' still unapplied on credit memo ' + cn.creditnote_number + '.');
  }

  const first = refunds[0] || {};
  const zohoRefundId = String(first.creditnote_refund_id || first.refund_id || '');
  const refundDate = /^\d{4}-\d{2}-\d{2}$/.test(String(first.date || ''))
    ? String(first.date)
    : String(cn.date || '').slice(0, 10);

  const payload = {
    externalId: 'REFUND-' + cn.creditnote_number,
    tranId: String(cfg.refundPrefix) + cn.creditnote_number,
    customer: { id: String(cm.entity.id) },
    account: { id: String(cfg.bankAccountId) },
    tranDate: refundDate,
    memo: 'Zoho refund on credit note ' + cn.creditnote_number + (zohoRefundId ? ' (Zoho refund ' + zohoRefundId + ')' : ''),
    // Tags the refund to the credit memo this run just created.
    apply: { items: [{ doc: { id: String(cm.id) }, apply: true, amount }] },
  };
  if (cm.currency && cm.currency.id) payload.currency = { id: String(cm.currency.id) };
  if (cm.subsidiary && cm.subsidiary.id) payload.subsidiary = { id: String(cm.subsidiary.id) };
  const locationId = (cm.location && cm.location.id) || cfg.defaultLocationId;
  if (locationId) payload.location = { id: String(locationId) };

  return result({
    refund_ready: true,
    refund_payload: payload,
    refund_amount: amount,
    refund_number: payload.tranId,
    creditmemo_id: String(cm.id),
    creditmemo_balance: remaining,
    creditnote_id: cn.creditnote_id,
    creditnote_number: cn.creditnote_number,
    zoho_refund_id: zohoRefundId,
  });
} catch (e) {
  return result({
    refund_ready: false,
    refund_amount: 0,
    creditnote_number: cn.creditnote_number,
    error: e.message,
  });
}

