  const status = Number(raw.statusCode || raw.error?.statusCode || raw.error?.httpCode || 0);
  return { status, body: body || {}, error: raw.error, headers: raw.headers || {} };
}
function errorText(r) {
  const details = r.body?.['o:errorDetails'];
  if (Array.isArray(details) && details.length) return details.map(d => d.detail || d.message).join('; ');
  return String(r.body?.detail || r.body?.message || r.error?.message || r.error || ('HTTP ' + r.status));
}
