const data = $('Prepare Credit Note Refund').first().json;
const postedRaw = $('Create Customer Refund').first().json || {};
const posted = readResponse(postedRaw);
const readBack = readResponse($input.first().json);

const postMessage = errorText(posted);
const postedOk = !posted.error && posted.status >= 200 && posted.status < 300;
// A rerun hits the same external ID; NetSuite reports that as a duplicate.
const duplicate = !postedOk && /already exist|duplicate/i.test(postMessage);

if (!postedOk && !duplicate) {
  return result({ ...data, refund_complete: false, error: 'NetSuite rejected the customer refund: ' + postMessage });
}

const location = String(postedRaw.headers?.location || postedRaw.headers?.Location || '');
const idFromLocation = (location.match(/(\d+)\s*$/) || [])[1] || '';
const refundId = String(readBack.body?.id || posted.body?.id || idFromLocation || '');

if (!refundId) {
  return result({ ...data, refund_complete: false, error: (duplicate
    ? 'A customer refund with external ID ' + data.refund_payload.externalId + ' already exists but could not be read back: '
    : 'NetSuite accepted the refund but it could not be read back: ') + errorText(readBack) });
}

const expectedTranId = String(data.refund_payload.tranId || '');
const actualTranId = readBack.body?.tranId ? String(readBack.body.tranId) : '';
const appliedLines = (readBack.body?.apply?.items || []).filter(line => line.apply === true);
const appliedToMemo = appliedLines.some(line => String(line.doc?.id ?? line.doc) === String(data.creditmemo_id));

if (appliedLines.length > 0 && !appliedToMemo) {
  return result({ ...data, refund_complete: false, refund_id: refundId,
    error: 'Customer refund ' + (actualTranId || expectedTranId) + ' (NetSuite ID ' + refundId +
      ') was created but is not applied to credit memo ' + data.creditnote_number + '.' });
}

const notes = [];
const readBackOk = !readBack.error && readBack.status >= 200 && readBack.status < 300 && !!readBack.body?.id;
if (!readBackOk) {
  notes.push('The refund was accepted by NetSuite but could not be read back, so its document number and credit memo application are unconfirmed: ' + errorText(readBack));
}
if (actualTranId && expectedTranId && actualTranId !== expectedTranId) {
  notes.push('NetSuite assigned document number ' + actualTranId + ' instead of ' + expectedTranId +
    '; tick "Allow Override" for Customer Refund under Setup > Company > Auto-Generated Numbers to keep the Zoho-based number.');
}

return result({ ...data,
  refund_complete: true,
  refund_existing: duplicate,
  refund_id: refundId,
  refund_document_number: actualTranId || expectedTranId,
  refund_applied_to_memo: appliedToMemo,
  refund_notes: notes.join(' '),
});

